+/**
+ * A contact form: fill it in, press Send, and the message shows up in the list
+ * below. Leaving the view with something typed in asks before throwing it away.
+ */
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL = Pattern.compile(EmailValidator.PATTERN);
+
+    private final MessageStore store;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final List<TextFieldBase<?, String>> inputs = List.of(name, email, phone, message);
+
+    private final Button send = new Button("Send");
+    private final Grid<Message> messages = new Grid<>();
+    /** One instance, reopened on every send, so sending twice never stacks up two of them. */
+    private final Notification sent = new Notification("Message sent");
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+
+        for (TextFieldBase<?, String> input : inputs) {
+            // Validation is entirely ours: a field never marks itself invalid
+            // nor replaces one of the error messages below.
+            input.setManualValidation(true);
+            input.setValueChangeMode(ValueChangeMode.EAGER);
+            // Editing anything makes Send available again and drops a stale error.
+            input.addValueChangeListener(event -> {
+                send.setEnabled(true);
+                clearError(input);
+            });
+        }
+
+        sent.setDuration(3000);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        messages.addColumn(Message::name).setHeader("Name").setAutoWidth(true);
+        messages.addColumn(Message::message).setHeader("Message").setFlexGrow(1);
+        messages.addColumn(Message::email).setHeader("Email").setAutoWidth(true);
+        messages.addColumn(Message::phone).setHeader("Phone").setAutoWidth(true);
+        messages.setAllRowsVisible(true);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setColspan(message, 2);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send,
+                new Paragraph("Messages sent so far"), messages);
+
+        refreshMessages();
+    }
+
+    private void trySend() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        String nameValue = trimmed(name);
+        String emailValue = trimmed(email);
+        String phoneValue = trimmed(phone);
+        String messageValue = value(message);
+
+        boolean valid = true;
+
+        if (nameValue.isEmpty()) {
+            setError(name, "Name is required");
+            valid = false;
+        }
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            setError(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            setError(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageValue.trim().isEmpty()) {
+            setError(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            setError(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            // Nothing is sent, and what the user typed stays where it is.
+            return;
+        }
+
+        // The list shows what the user actually sent, untrimmed.
+        store.add(new Message(value(name), value(email), value(phone), messageValue));
+        refreshMessages();
+
+        clearForm();
+        // Send stays disabled until the next edit of any field.
+        send.setEnabled(false);
+
+        sent.open();
+    }
+
+    private void clearForm() {
+        for (TextFieldBase<?, String> input : inputs) {
+            input.clear();
+            clearError(input);
+        }
+    }
+
+    private void refreshMessages() {
+        messages.setItems(store.all());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (isEmpty()) {
+            // Nothing to lose, so do not get in the way.
+            return;
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard this message?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            dialog.close();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.add(new Paragraph("You have not sent your message yet."),
+                new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+
+    private boolean isEmpty() {
+        return inputs.stream().allMatch(input -> trimmed(input).isEmpty());
+    }
+
+    private static String value(TextFieldBase<?, String> input) {
+        String value = input.getValue();
+        return value == null ? "" : value;
+    }
+
+    private static String trimmed(TextFieldBase<?, String> input) {
+        return value(input).trim();
+    }
+
+    private static void setError(TextFieldBase<?, String> input, String errorMessage) {
+        input.setErrorMessage(errorMessage);
+        input.setInvalid(true);
+    }
+
+    private static void clearError(TextFieldBase<?, String> input) {
+        input.setInvalid(false);
+        input.setErrorMessage(null);
+    }
+}
