+package com.example.contact;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * Keeps the messages that have been sent, newest first.
+ *
+ * <p>
+ * The messages live in the Vaadin session, so they outlive a single visit to
+ * the contact view: navigating away and back shows them again. Nothing is
+ * written to disk.
+ * </p>
+ */
+@Service
+public class MessageStore implements Serializable {
+
+    private static final String ATTRIBUTE = MessageStore.class.getName() + ".messages";
+
+    /** Used only when there is no Vaadin session at all, e.g. in a plain unit test. */
+    private final List<Message> detached = new ArrayList<>();
+
+    /** Adds a message as the newest one. */
+    public synchronized void add(Message message) {
+        messages().add(0, message);
+    }
+
+    /** All messages sent so far, newest first. */
+    public synchronized List<Message> all() {
+        return List.copyOf(messages());
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<Message> messages() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            return detached;
+        }
+        List<Message> messages = (List<Message>) session.getAttribute(ATTRIBUTE);
+        if (messages == null) {
+            messages = Collections.synchronizedList(new ArrayList<>());
+            session.setAttribute(ATTRIBUTE, messages);
+        }
+        return messages;
+    }
+}
