+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+        lookUpFields();
+    }
+
+    private void lookUpFields() {
+        name = find(TextField.class).withLabel("Name").single();
+        email = find(EmailField.class).withLabel("Email").single();
+        phone = find(TextField.class).withLabel("Phone").single();
+        message = find(TextArea.class).withLabel("Message").single();
+        send = find(Button.class).withText("Send").single();
+    }
+
+    private void fillValidForm() {
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello there");
+    }
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    @Test
+    void viewHasHeadingLinkAndEmptyEnabledForm() {
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled(), "Send must be enabled on an untouched form");
+        assertFalse(name.isInvalid());
+        assertFalse(email.isInvalid());
+        assertFalse(message.isInvalid());
+    }
+
+    @Test
+    void emptyFormReportsEveryFailedRule() {
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertEquals(0, test(grid()).size());
+        assertFalse(find(Notification.class).exists());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void invalidEmailIsReported() {
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello");
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertEquals(0, test(grid()).size());
+        assertEquals("Ada", name.getValue(), "what the user typed must stay in the form");
+    }
+
+    @Test
+    void phoneAloneIsEnough() {
+        test(name).setValue("Ada");
+        test(phone).setValue("+358 40 123 4567");
+        test(message).setValue("Call me");
+
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessageIsReported() {
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void exactlyFiveHundredCharactersIsAccepted() {
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("x".repeat(500));
+
+        test(send).click();
+
+        assertFalse(message.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void sendingAddsRowNotifiesAndResetsTheForm() {
+        fillValidForm();
+
+        test(send).click();
+
+        assertTrue(find(Notification.class).exists());
+        assertTrue(test(find(Notification.class).single()).getText().contains("Message sent"));
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertFalse(send.isEnabled(), "Send is disabled right after a successful send");
+
+        test(name).setValue("Grace");
+        assertTrue(send.isEnabled(), "editing a field enables Send again");
+    }
+
+    @Test
+    void newestMessageComesFirst() {
+        fillValidForm();
+        test(send).click();
+
+        test(name).setValue("Grace");
+        test(email).setValue("grace@example.com");
+        test(message).setValue("Second message");
+        test(send).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Grace", test(grid()).getCellText(0, 0));
+        assertEquals("Ada", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void enterSendsTheForm() {
+        fillValidForm();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("", name.getValue());
+    }
+
+    @Test
+    void messagesSurviveLeavingAndComingBack() {
+        fillValidForm();
+        test(send).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        lookUpFields();
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        navigate(AboutView.class);
+
+        assertFalse(find(Dialog.class).exists());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void keepEditingStaysOnTheContactView() {
+        test(name).setValue("Ada");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(find(Dialog.class).exists(), "a dialog must ask before losing the text");
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals("Ada", find(TextField.class).withLabel("Name").single().getValue());
+    }
+
+    @Test
+    void discardGoesAhead() {
+        test(message).setValue("Half written");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(find(Dialog.class).exists());
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void navigationFromAnywhereElseIsAlsoGuarded() {
+        test(phone).setValue("123456");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue(find(Dialog.class).exists());
+        assertTrue(getCurrentView() instanceof ContactView);
+    }
+}
